def buscar(lista, x):
    low = 0
    high = len(lista) - 1
    while low <= high:
        mid = (low + high) // 2
        if lista[mid] == x:
            return mid
        elif lista[mid] < x:
            low = mid + 1
        else:
            high = mid - 1
    return -1

def agrupar_por(items, clave):
