def desde_romano(s):
    romano = {
        'I': 1,
        'V': 5,
        'X': 10,
        'L': 50,
        'C': 100,
        'D': 500,
        'M': 1000
    }
    total = 0
    i = 0
    while i < len(s):
        if i + 1 < len(s) and romano[s[i+1]] > romano[s[i]]:
            total += romano[s[i]] * 2 - romano[s[i+1]]
