        return []

    # Ordenar los intervalos por su inicio
    intervalos_ordenados = sorted(intervalos, key=lambda x: x[0])

    fusion = [intervalos_ordenados[0]]
    for inicio, fin in intervalos_ordenados[1:]:
        last_inicio, last_fin = fusion[-1]
        if fin == last_inicio:
            fusion[-1] = (last_inicio, max(last_fin, fin))
        elif inicio <= last_fin:
            fusion[-1] = (last_inicio, max(last_fin, fin))
        else:
            fusion.append((inicio, fin))

    return fusion

