def promedio_movil(nums, ventana):
    if not nums or len(nums) < ventana:
        return []
    resultado = []
    current_sum = sum(nums[:ventana])
    resultado.append(current_sum / ventana)
    for i in range(ventana, len(nums)):
        current_sum += nums[i] - nums[i - ventana]
        resultado.append(current_sum / ventana)
    return resultado

