def contar_islas(grid):
    if not grid:
        return 0

    rows, cols = len(grid), len(grid[0])
    visited = [[False for _ in range(cols)] for _ in range(rows)]
    count = 0

    def dfs(r, c):
        if not 0 <= r < rows or not 0 <= c < cols or grid[r][c] == 0 or visited[r][c]:
            return
        visited[r][c] = True
        for dr, dc in [(0, 1), (1, 0), (0, -1), (-1, 0)]:
            dfs(r + dr, c + dc)

    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 1 and not visited[r][c]:
                dfs(r, c)
                count += 1

    return count

def distancia(a, b):
    m = len(a)
    n = len(b)
    # Crear una matriz de tamaño (m+1) x (n+1)
    dp = [[0] * (n + 1) for _ in range(m + 1)]

    # Inicializar la primera fila
    for i in range(m + 1):
        dp[i][0] = i

    # Inicializar la primera columna
    for j in range(n + 1):
        dp[0][j] = j

    # llenar la matriz
    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if a[i-1] == b[j-1]:
                dp[i][j] = dp[i-1][j-1]
            else:
                dp[i][j] = min(dp[i-1][j], dp[i][j-1], dp[i-1][j-1]) + 1

    return dp[m][n]

def a_base(n, base):
    if n == 0:
        return '0'
    digits = '0123456789abcdef'
    result = ''
    while n > 0:
        result = digits[n % base] + result
        n = n // base
    return result

