def sumar_romanos(a, b):
    # Diccionario que mapea las letras romanas a sus valores numéricos
    romano_a_numeros = {
        'I': 1, 'V': 5, 'X': 10, 'L': 50, 'C': 100, 'D': 500, 'M': 1000,
        'IV': 4, 'IX': 9, 'XL': 40, 'XC': 90, 'CD': 400, 'CM': 900
    }

    # Convertir los strings romanos a números
    num_a = 0
    i = 0
    while i < len(a):
        if i + 1 < len(a) and romano_a_numeros.get(a[i+1], 0) > romano_a_numeros.get(a[i], 0):
            num_a += romano_a_numeros[a[i]] + romano_a_numeros[a[i+1]]
            i += 2
        else:
            num_a += romano_a_numeros[a[i]]
            i += 1

    num_b = 0
    j = 0
    while j < len(b):
        if j + 1 < len(b) and romano_a_numeros.get(b[j+1], 0) > romano_a_numeros.get(b[j], 0):
            num_b += romano_a_numeros[b[j]] + romano_a_numeros[b[j+1]]
            j += 2
        else:
            num_b += romano_a_numeros[b[j]]
            j += 1

    total = num_a + num_b

    # Convertir el número total a romano
    def numero_a_romano(n):
        romanos = [
            (1000, 'M'), (900, 'CM'), (500, 'D'), (400, 'CD'),
            (100, 'C'), (90, 'XC'), (50, 'L'), (40, 'XL'),
            (10, 'X'), (9, 'IX'), (5, 'V'), (4, 'IV'), (1, 'I')
        ]
        resultado = ''
        for valor, simbolo in romanos:
            while n >= valor:
                resultado += simbolo
                n -= valor
        return resultado

    return numero_a_romano(total)

def atender(tareas):
    # Ordenar las tareas por prioridad ascendente, y si hay igualdad, por el nombre
    return sorted(tareas, key=lambda x: (x[0], x[1]))

def obtener(d, camino, defecto=None):
    partes = camino.split('.')
    actual = d
    for parte in partes:
        if parte in actual:
            actual = actual[parte]
        else:
            return defecto
    return actual

def con_reintentos(fn, veces):
